//! Cold DSL handlers. Auto-generated by `lyng-js-dsl-codegen` (B46–B47).
//!
//! Each Cold opcode gets:
//! 1. A `#[unsafe(naked)] extern "C" fn op_xxx_dsl()` handler
//!    emitted by `llint_handler!`. The body is a single
//!    `call_slow!(op_xxx_slow_rs, args = [...]); dispatch_after_slow!();`
//!    pair — every cold opcode pays the slow-path round-trip.
//! 2. A `extern "C" fn op_xxx_slow_rs(state, ...) -> SlowPathReturn`
//!    shim that reconstructs the args struct from raw u32 operand
//!    slots, calls the semantic body in
//!    `crate::vm::semantics::<family>::op_xxx_semantic`, and
//!    translates the outcome back to `SlowPathReturn`.
//!
//! DO NOT EDIT BY HAND. Re-run `cargo run -p lyng-js-dsl-codegen`
//! after touching `tools/lyng-js-dsl-codegen/src/main.rs`.

#[cfg(target_arch = "aarch64")]
use crate::{
    call_slow, cmp_branch_eq, decode_a, decode_ab, decode_abc, decode_abc_slot,
    decode_abx, decode_ax, dispatch, dispatch_after_slow, load_acc, load_constant,
    load_local_fixed, load_reg, load_state_value, load_uninit_lex_sentinel,
    store_acc, store_local_fixed, store_reg, tag_bool_const, tag_null,
    tag_smi_const, tag_smi_from_signed_byte, tag_undefined,
};

#[cfg(target_arch = "aarch64")]
use lyng_js_vm_dsl::llint_handler;

/// Helper namespace for cold-stub shim utilities.
#[cfg(target_arch = "aarch64")]
struct ColdShimHelpers;

#[cfg(target_arch = "aarch64")]
impl ColdShimHelpers {
    /// Read a 2-byte feedback-slot index from `[PC + offset]`
    /// of the active frame's bytecode, returning the typed slot id.
    /// Used by IC-bearing opcodes whose asm prologue can't fit
    /// the slot operand (e.g. `LoadGlobal`'s Abx layout reads
    /// the first 4 bytes; the slot is at bytes 4..6).
    ///
    /// `FeedbackSlotId::from_raw(0)` returns `None` (slot 0 is
    /// the sentinel for "no feedback"); a non-zero raw index
    /// returns `Some`. Either way the caller receives an
    /// `Option<FeedbackSlotId>` that maps directly into the
    /// `feedback_slot` field on the args struct.
    #[inline]
    fn feedback_slot_from_pc(
        state: &mut crate::dsl::slow_path::LlIntDispatchState<'_, '_>,
        offset: u32,
    ) -> Option<lyng_js_types::FeedbackSlotId> {
        let inner = state.dispatch_state();
        let pc = inner.frame.instruction_offset();
        // SAFETY: `installed.function.instruction_bytes()` is a
        // pub(crate) field reachable through the active frame's
        // installed function (held in `DispatchState.installed`).
        let bytes = inner.installed.function().instruction_bytes();
        let lo = bytes.get((pc + offset) as usize).copied()? as u32;
        let hi = bytes.get((pc + offset + 1) as usize).copied()? as u32;
        let raw = lo | (hi << 8);
        lyng_js_types::FeedbackSlotId::from_raw(raw)
    }

    /// Read the inline `CallRange` (4 bytes — count, base) from the
    /// current instruction at `[PC + offset]`. Used by the variable-arity
    /// `Call` / `TailCall` / `Construct` cold shims to mirror the α
    /// handler's `decode_call_range_operands` path. Layout per
    /// `decode_call_range_operands`: bytes 4,5 = count_lo/hi; bytes 6,7 =
    /// base_lo/hi. The slot operand follows at bytes 8,9.
    #[inline]
    fn call_range_from_pc(
        state: &mut crate::dsl::slow_path::LlIntDispatchState<'_, '_>,
        offset: u32,
    ) -> lyng_js_bytecode::CallRange {
        let inner = state.dispatch_state();
        let pc = inner.frame.instruction_offset();
        let bytes = inner.installed.function().instruction_bytes();
        let count_lo = bytes.get((pc + offset) as usize).copied().unwrap_or(0);
        let count_hi = bytes.get((pc + offset + 1) as usize).copied().unwrap_or(0);
        let base_lo = bytes.get((pc + offset + 2) as usize).copied().unwrap_or(0);
        let base_hi = bytes.get((pc + offset + 3) as usize).copied().unwrap_or(0);
        let count = u16::from_le_bytes([count_lo, count_hi]);
        let base = u16::from_le_bytes([base_lo, base_hi]);
        lyng_js_bytecode::CallRange::new(base, count)
    }

    /// Look up the `spread_mask` metadata for an optional feedback slot.
    /// Mirrors `calls::spread_mask_for_semantic` in the α path: returns
    /// `None` when there's no slot or no spread metadata.
    #[inline]
    fn spread_mask_for(
        state: &mut crate::dsl::slow_path::LlIntDispatchState<'_, '_>,
        feedback_slot: Option<lyng_js_types::FeedbackSlotId>,
    ) -> Option<u64> {
        let slot = feedback_slot?;
        let inner = state.dispatch_state();
        let descriptor = inner.installed.feedback_descriptor_for_slot(slot)?;
        descriptor.metadata().spread_mask()
    }

    /// Convenience: look up `spread_mask` directly from the feedback
    /// slot at `[PC + offset]`. Combines `feedback_slot_from_pc` with
    /// `spread_mask_for` so the cold shim can express the lookup as a
    /// single field expression in the args struct literal (without
    /// needing a let-binding for the intermediate slot).
    #[inline]
    fn spread_mask_from_pc(
        state: &mut crate::dsl::slow_path::LlIntDispatchState<'_, '_>,
        offset: u32,
    ) -> Option<u64> {
        let feedback_slot = Self::feedback_slot_from_pc(state, offset);
        Self::spread_mask_for(state, feedback_slot)
    }
}

